"""Core domain schemas, Pydantic models, and workflow state models."""

from datetime import datetime, timezone
from typing import Any, Dict, List, Literal, Optional
from pydantic import BaseModel, Field


class ResearchFindings(BaseModel):
    """Structured output generated by the Researcher Agent."""
    summary: str = Field(description="Executive summary of the research investigation.")
    identified_facts: List[str] = Field(
        default_factory=list,
        description="Discrete, atomic factual statements established by evidence."
    )
    supporting_evidence: List[str] = Field(
        default_factory=list,
        description="Direct quotes, code excerpts, or data backing identified facts."
    )
    source_references: List[str] = Field(
        default_factory=list,
        description="File paths, line numbers, URLs, or document identifiers."
    )
    uncertainties: List[str] = Field(
        default_factory=list,
        description="Ambiguities, unverified assumptions, or potential gaps."
    )
    unanswered_questions: List[str] = Field(
        default_factory=list,
        description="Remaining questions requiring external human input or further investigation."
    )


class DraftReport(BaseModel):
    """Structured report produced by the Writer Agent from verified research findings."""
    title: str = Field(description="Headline describing the synthesis.")
    executive_summary: str = Field(description="High-level overview grounded in verified facts.")
    detailed_analysis: str = Field(
        description="Comprehensive technical analysis with explicit citations (e.g. [Source: file.py#L10])."
    )
    cited_sources: List[str] = Field(
        default_factory=list,
        description="List of all sources referenced in the analysis."
    )
    confidence_score: float = Field(
        default=1.0,
        ge=0.0,
        le=1.0,
        description="Self-assessed grounding confidence score between 0.0 and 1.0."
    )


class JudgeFeedback(BaseModel):
    """Structured evaluation returned by the independent Judge Agent."""
    status: Literal["pass", "fail"] = Field(
        description="Whether the draft meets accuracy and grounding standards ('pass' or 'fail')."
    )
    overall_score: float = Field(
        ge=0.0,
        le=5.0,
        description="Overall quality assessment score from 0.0 to 5.0."
    )
    hallucination_score: float = Field(
        ge=0.0,
        le=5.0,
        description="Hallucination score: 5.0 means zero unsupported claims; 0.0 means completely fabricated."
    )
    response_match_score: float = Field(
        ge=0.0,
        le=5.0,
        description="Response match score: 5.0 means perfect alignment with user query and expected facts."
    )
    unsupported_claims: List[str] = Field(
        default_factory=list,
        description="Any factual assertions in the draft not supported by researcher evidence."
    )
    missing_information: List[str] = Field(
        default_factory=list,
        description="Critical aspects of the user query or evidence omitted from the report."
    )
    revision_instructions: str = Field(
        description="Concrete, actionable feedback for the next refinement iteration."
    )


class AgentTrajectoryStep(BaseModel):
    """Recorded discrete event in an agent execution trajectory."""
    step_number: int
    agent_name: str
    action: str
    tool_name: Optional[str] = None
    tool_input: Optional[Dict[str, Any]] = None
    tool_output: Optional[str] = None
    canonical_event: str
    timestamp: float
    iteration: int = 1
    details: Dict[str, Any] = Field(default_factory=dict)


class AgentExecutionMetrics(BaseModel):
    """Telemetry metrics accumulated for a specific agent role."""
    agent_name: str
    input_tokens: int = 0
    output_tokens: int = 0
    total_tokens: int = 0
    cost_usd: Optional[float] = 0.0
    latency_ms: float = 0.0
    call_count: int = 0


class WorkflowExecutionState(BaseModel):
    """Comprehensive shared state of a multi-agent workflow execution."""
    request_id: str
    trace_id: str
    task: str
    repo_url: Optional[str] = None
    current_iteration: int = 1
    max_iterations: int = 3
    status: Literal["pending", "running", "approved", "max_iterations_reached", "failed"] = "pending"
    research_findings: Optional[ResearchFindings] = None
    draft_report: Optional[DraftReport] = None
    judge_feedback: Optional[JudgeFeedback] = None
    revision_history: List[Dict[str, Any]] = Field(default_factory=list)
    trajectory: List[AgentTrajectoryStep] = Field(default_factory=list)
    agent_metrics: Dict[str, AgentExecutionMetrics] = Field(default_factory=dict)
    total_input_tokens: int = 0
    total_output_tokens: int = 0
    total_tokens: int = 0
    total_cost_usd: Optional[float] = 0.0
    total_latency_ms: float = 0.0
    final_response: Optional[str] = None
    is_mock: bool = False
    created_at: str = Field(default_factory=lambda: datetime.now(timezone.utc).isoformat())
    completed_at: Optional[str] = None
    error_message: Optional[str] = None

    def record_step(
        self,
        agent_name: str,
        action: str,
        canonical_event: str,
        tool_name: Optional[str] = None,
        tool_input: Optional[Dict[str, Any]] = None,
        tool_output: Optional[str] = None,
        timestamp: Optional[float] = None,
        details: Optional[Dict[str, Any]] = None,
    ) -> AgentTrajectoryStep:
        """Append an event to the execution trajectory."""
        import time
        ts = timestamp if timestamp is not None else time.time()
        step = AgentTrajectoryStep(
            step_number=len(self.trajectory) + 1,
            agent_name=agent_name,
            action=action,
            tool_name=tool_name,
            tool_input=tool_input,
            tool_output=tool_output,
            canonical_event=canonical_event,
            timestamp=ts,
            iteration=self.current_iteration,
            details=details or {},
        )
        self.trajectory.append(step)
        return step

    def record_agent_metrics(
        self,
        agent_name: str,
        input_tokens: int,
        output_tokens: int,
        latency_ms: float,
        cost_usd: Optional[float] = None,
    ) -> None:
        """Update metrics for an agent and total request counters."""
        if agent_name not in self.agent_metrics:
            self.agent_metrics[agent_name] = AgentExecutionMetrics(agent_name=agent_name)

        m = self.agent_metrics[agent_name]
        m.input_tokens += input_tokens
        m.output_tokens += output_tokens
        m.total_tokens += (input_tokens + output_tokens)
        m.latency_ms += latency_ms
        m.call_count += 1
        if cost_usd is not None and m.cost_usd is not None:
            m.cost_usd += cost_usd

        self.total_input_tokens += input_tokens
        self.total_output_tokens += output_tokens
        self.total_tokens += (input_tokens + output_tokens)
        if cost_usd is not None and self.total_cost_usd is not None:
            self.total_cost_usd += cost_usd
